"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a line typed letter by letter, then deleted and replaced by the next one. */
export type TypewriterProps = Omit<ComponentPropsWithoutRef<"span">, "children" | "role" | "aria-label"> & {
  /** The lines to type, in order. Every line must make sense by itself. */
  lines: string[];
  /** Letters typed each second. Deleting runs twice as fast. */
  speed?: number;
  /** Milliseconds a finished line stays before it is deleted. */
  pause?: number;
  /** Starts again from the first line after the last. When false, the last line stays. */
  loop?: boolean;
  /** Holds the typing where it is. Pass it from a visible pause control when the lines loop. */
  paused?: boolean;
};

type Phase = "typing" | "holding" | "deleting";

interface Step {
  line: number;
  /** How many letters of the line are typed. */
  count: number;
  phase: Phase;
}

// The caret is on for half a second and off for half a second, with no fade between.
const BLINK: Transition = { duration: 1, times: [0, 0.5, 0.5, 1], ease: "linear", repeat: Infinity };

/** The next step. `whole` swaps complete lines, for people who asked for less motion. */
function advance(step: Step, lengths: number[], whole: boolean): Step {
  const length = lengths[step.line] ?? 0;
  const next = (step.line + 1) % lengths.length;
  if (step.phase === "typing") {
    return step.count < length ? { ...step, count: step.count + 1 } : { ...step, phase: "holding" };
  }
  if (step.phase === "holding") {
    return whole ? { line: next, count: lengths[next] ?? 0, phase: "holding" } : { ...step, phase: "deleting" };
  }
  return step.count > 0 ? { ...step, count: step.count - 1 } : { line: next, count: 0, phase: "typing" };
}

/**
 * Types a line letter by letter with a caret, holds it, deletes it and types
 * the next. The longest line reserves the space, so nothing around it moves.
 * Assistive technology reads the whole current line from the label and never
 * the half-typed letters. With reduced motion each line appears whole.
 */
export function Typewriter({ lines, speed = 22, pause = 1800, loop = true, paused = false, className, ...spanProps }: TypewriterProps) {
  const reduceMotion = useReducedMotion();
  const [step, setStep] = useState<Step>({ line: 0, count: 0, phase: "typing" });
  // A parent can pass a shorter list mid-run, so never read past its end.
  const line = lines.length > 0 ? step.line % lines.length : 0;
  const letters = [...(lines[line] ?? "")];
  const lengths = lines.map((entry) => [...entry].length);
  const whole = Boolean(reduceMotion);
  const count = whole ? letters.length : Math.min(step.count, letters.length);
  const phase: Phase = whole ? "holding" : step.phase;
  const lastLine = line === lines.length - 1;
  // The last line stays when nothing follows it. A lone line shown whole has nothing left to do.
  const finished = lines.length === 0 || (phase === "holding" && ((lastLine && !loop) || (whole && lines.length < 2)));
  const lengthsKey = lengths.join(",");

  useEffect(() => {
    if (paused || finished) return;
    const delay = phase === "holding" ? pause : (phase === "deleting" ? 500 : 1000) / Math.max(speed, 1);
    const sizes = lengthsKey.split(",").map(Number);
    const timer = window.setTimeout(() => setStep(advance({ line, count, phase }, sizes, whole)), delay);
    return () => window.clearTimeout(timer);
  }, [paused, finished, phase, line, count, pause, speed, whole, lengthsKey]);

  return (
    <span
      {...spanProps}
      // An image role is the one that makes every screen reader speak the label and skip the letters.
      role="img"
      aria-label={lines[line] ?? ""}
      data-phase={phase}
      className={cn("inline-grid text-left", className)}
    >
      {lines.map((entry, index) => (
        // Invisible copies of every line size the box. The trailing space keeps room for the caret.
        <span key={index} aria-hidden="true" className="invisible col-start-1 row-start-1 whitespace-pre-wrap">
          {entry}{" "}
        </span>
      ))}
      <span aria-hidden="true" data-typed="" className="col-start-1 row-start-1 whitespace-pre-wrap">
        {letters.slice(0, count).join("")}
        <motion.span
          data-caret=""
          // The caret holds steady while letters move and blinks only when the line rests.
          animate={phase === "holding" && !whole && !paused ? { opacity: [1, 1, 0, 0] } : { opacity: 1 }}
          transition={phase === "holding" && !whole && !paused ? BLINK : { duration: 0 }}
          className="ml-0.5 inline-block h-lh w-0.5 rounded-full bg-current align-top"
        />
      </span>
    </span>
  );
}
